static <K, V> Map<K, V> lru(int maxEntries) {
    return Collections.synchronizedMap(new LinkedHashMap<K, V>(16, 0.75f, true) {
        @Override protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > maxEntries;
        }
    });
}

